new_public=r'''function Public({data,setData,onLogin}){\n const [view,setView]=useState(()=>{try{return localStorage.getItem('ka-shali-website-admin-session')==='1'?'website-admin':'home'}catch{return 'home'}});\n const site=data.website||WEBSITE_DEFAULTS;\n if(view==='website-admin')return <WebsiteAdmin data={data} setData={setData} onExit={()=>{try{localStorage.removeItem('ka-shali-website-admin-session')}catch{};setView('home')}}/>;\n if(view==='website-admin-login')return <WebsiteAdminLogin onBack={()=>setView('home')} onSuccess={()=>{try{localStorage.setItem('ka-shali-website-admin-session','1')}catch{};setView('website-admin')}}/>;\n if(view==='login')return <PublicFormPage title="Welcome back" onBack={()=>setView('home')}><LoginForm data={data} setData={setData} onLogin={onLogin}/></PublicFormPage>;\n if(view==='register')return <PublicFormPage title="Create your school account" onBack={()=>setView('home')}><RegisterForm data={data} setData={setData} onDone={()=>setView('home')}/></PublicFormPage>;\n if(view==='find')return <div className="public"><FlagWatermark/><PublicHeader go={setView}/><SchoolProfile site={site} school={data.schools?.[0]||seedSchool} onBack={()=>setView('home')} onLogin={()=>setView('login')}/><PublicFooter site={site} go={setView}/></div>;\n if(view==='courses')return <div className="public"><FlagWatermark/><PublicHeader go={setView}/><CoursesClasses site={site} go={setView}/><PublicFooter site={site} go={setView}/></div>;\n if(view==='gallery')return <div className="public"><FlagWatermark/><PublicHeader go={setView}/><GalleryPage site={site} go={setView}/><PublicFooter site={site} go={setView}/></div>;\n return <div className="public"><FlagWatermark/><PublicHeader go={setView}/><Home site={site} go={setView}/><PublicFooter site={site} go={setView}/></div>;\n}\nfunction PublicHeader({go}){\n const scrollTo=id=>{const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'});else{go('home');setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'}),80)}};\n return <header className="ksSiteHeader"><div className="ksHeaderInner">\n  <button className="ksBrand" onClick={()=>go('home')} aria-label="Ka-Shali Pro-Learning Christian Academy home"><img src="./school-logo.png" alt={SCHOOL_NAME}/><span><strong>KA-SHALI PRO-LEARNING</strong><small>CHRISTIAN ACADEMY</small></span></button>\n  <nav className="ksMainNav" aria-label="Main navigation"><button className="active" onClick={()=>go('home')}>Home</button><button onClick={()=>go('find')}>About</button><button onClick={()=>go('courses')}>Courses</button><button onClick={()=>go('gallery')}>Gallery</button><button onClick={()=>scrollTo('ksContact')}>Contact</button></nav>\n  <div className="ksHeaderActions"><button className="ksLoginBtn" onClick={()=>go('login')}>Portal Login</button><button className="ksRegisterBtn" onClick={()=>go('register')}>Register</button></div>\n </div></header>}\nfunction Home({site,go}){\n const slides=site.heroSlides?.length?site.heroSlides:WEBSITE_DEFAULTS.heroSlides; const [slide,setSlide]=useState(0);\n useEffect(()=>{const t=setInterval(()=>setSlide(x=>(x+1)%slides.length),6000);return()=>clearInterval(t)},[slides.length]); const current=slides[Math.min(slide,slides.length-1)];\n return <main className="ksProfessionalHome">\n  <section className="ksHeroPro" aria-label="School highlights">\n   {slides.map((item,i)=><div key={item.id||item.image+i} className={'ksHeroSlide '+(i===slide?'active':'')}><img src={item.image} alt={item.title||SCHOOL_NAME}/><div className="ksHeroOverlay"/></div>)}\n   <button className="ksHeroArrow left" onClick={()=>setSlide(x=>(x-1+slides.length)%slides.length)} aria-label="Previous slide"><ChevronLeft size={25}/></button><button className="ksHeroArrow right" onClick={()=>setSlide(x=>(x+1)%slides.length)} aria-label="Next slide"><ChevronRight size={25}/></button>\n   <div className="ksHeroContent"><span className="ksHeroEyebrow">{current.eyebrow}</span><h1>{current.title}</h1><p>{current.text}</p><div className="ksHeroButtons"><button className="ksGoldBtn" onClick={()=>go('register')}>Enrol at Ka-Shali <ChevronRight size={17}/></button><button className="ksOutlineBtn" onClick={()=>go('find')}>Discover our school <ChevronRight size={17}/></button></div></div>\n   <div className="ksHeroBadge"><img src="./school-logo.png" alt={SCHOOL_NAME}/></div><div className="ksHeroDots">{slides.map((_,i)=><button key={i} className={i===slide?'active':''} onClick={()=>setSlide(i)} aria-label={'Show slide '+(i+1)}/>)}</div>\n  </section>\n  <section className="ksWelcomeSection"><div className="ksSectionIntro"><span className="ksEyebrow">WELCOME TO KA-SHALI</span><h2>{site.welcomeTitle}</h2><p>{site.welcomeText}</p></div><div className="ksReasonGrid">{(site.reasons||[]).slice(0,3).map((r,i)=><article key={r.title+i}><div className="ksReasonIcon">{i===0?<GraduationCap/>:i===1?<ShieldCheck/>:<Users/>}</div><h3>{r.title}</h3><p>{r.text}</p></article>)}</div></section>\n  <section className="ksAboutHome"><div className="ksAboutImage"><img src="./gallery/school-group-1.jpg" alt="Ka-Shali Pro-Learning Christian Academy school community"/></div><div className="ksAboutCopy"><span className="ksEyebrow">ABOUT THE SCHOOL</span><h2>{site.aboutTitle}</h2><p>{site.aboutText}</p><div className="ksAboutActions"><button className="ksDarkBtn" onClick={()=>go('find')}>About the school <ChevronRight size={17}/></button><button className="ksTextBtn" onClick={()=>go('courses')}>View courses & classes <ChevronRight size={17}/></button></div></div></section>\n  <section className="ksAdmissionBand"><div><span className="ksEyebrow light">ADMISSIONS</span><h2>{site.admissionTitle}</h2><p>{site.admissionText}</p></div><button className="ksGoldBtn" onClick={()=>go('register')}>Start an application <ChevronRight size={17}/></button></section>\n  <section className="ksContactSection" id="ksContact"><div className="ksContactIntro"><span className="ksEyebrow">CONTACT THE SCHOOL</span><h2>Speak to Ka-Shali.</h2><p>For admissions, programmes and school enquiries, contact the school directly.</p></div><div className="ksContactCards"><a href={`https://wa.me/${String(site.phone1||'').replace(/\D/g,'')}`} target="_blank" rel="noreferrer"><MessageCircle/><span><b>WhatsApp / Call</b><strong>{site.phone1}</strong></span></a><a href={`https://wa.me/${String(site.phone2||'').replace(/\D/g,'')}`} target="_blank" rel="noreferrer"><MessageCircle/><span><b>WhatsApp / Call</b><strong>{site.phone2}</strong></span></a><a href={`mailto:${site.email}`}><Mail/><span><b>Email</b><strong>{site.email}</strong></span></a></div></section>\n </main>}\nfunction SchoolProfile({site,school,onBack,onLogin}){const s=school||seedSchool;return <main className="schoolProfilePage"><section className="profileHero"><button className="backBtn" onClick={onBack}>← Back to home</button><img src="./school-logo.png" alt={SCHOOL_NAME}/><span className="ksEyebrow light">ABOUT THE SCHOOL</span><h1>{site.aboutTitle}</h1><p>{site.aboutText}</p></section><section className="profileBody"><div className="profileCopy"><h2>About {s.name}</h2><p>{site.aboutDetails}</p><p><b>Location:</b> {site.address||s.location}</p><p><b>Admissions:</b> {s.admission==='OPEN'?'Open for applications':'Contact the school for current admissions information.'}</p></div><div className="profileMotto"><img src="./school-logo.png" alt={SCHOOL_NAME}/><span>OUR MOTTO</span><h3>{site.motto}</h3></div></section><section className="profileCta"><h2>Ready to learn more?</h2><p>Explore the programmes or start an application.</p><div><button className="ksGoldBtn" onClick={()=>onLogin?.()}>Portal Login <ChevronRight size={17}/></button></div></section></main>}\nfunction CoursesClasses({site,go}){const courses=(site.courses||[]).filter(c=>c.visible!==false);return <main className="coursesPage"><section className="coursesHero"><button className="backBtn" onClick={()=>go('home')}>← Back to home</button><span className="ksEyebrow light">PROGRAMMES & COURSES</span><h1>Explore our learning programmes.</h1><p>Browse the programmes offered through Ka-Shali Pro-Learning Christian Academy.</p></section><section className="coursesGridPro">{courses.map(c=><article key={c.id}><span>{c.category||'Programme'}</span><h2>{c.title}</h2><p>{c.description}</p>{c.fee!=null&&<strong>School fee: E {Number(c.fee).toLocaleString()}</strong>}{c.monthly!=null&&<small>Monthly option: E {Number(c.monthly).toLocaleString()}</small>}<button className="ksTextBtn" onClick={()=>go('register')}>Apply for this programme <ChevronRight size={16}/></button></article>)}</section></main>}\nfunction GalleryPage({site,go}){const photos=site.gallery||[];return <main className="galleryPage"><section className="galleryHero"><button className="backBtn" onClick={()=>go('home')}>← Back to home</button><span className="ksEyebrow light">GALLERY</span><h1>Life at Ka-Shali.</h1><p>Explore photographs from the school website and see the people and community behind the school.</p></section><section className="galleryGridPro">{photos.map(p=><figure key={p.id||p.image}><img src={p.image} alt={p.title}/><figcaption><b>{p.title}</b><span>{p.text}</span></figcaption></figure>)}</section></main>}\nfunction PublicFooter({site,go}){return <footer className="ksSiteFooter"><div className="ksFooterContact"><a href={`https://wa.me/${String(site.phone1||'').replace(/\D/g,'')}`} target="_blank" rel="noreferrer"><MessageCircle/><span><b>WhatsApp</b><small>{site.phone1}</small></span></a><a href={`mailto:${site.email}`}><Mail/><span><b>Email</b><small>{site.email}</small></span></a></div><div className="ksFooterBrand"><img src="./school-logo.png" alt={SCHOOL_NAME}/><strong>{site.siteName||SCHOOL_NAME}</strong><span>{site.motto}</span></div><div className="ksFooterLinks"><button onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}>Back to top ↑</button><button onClick={()=>go('website-admin-login')}>Website Admin</button><button onClick={()=>go('login')}>EduLink Portal</button><small>{site.address}</small></div></footer>}\n\nfunction WebsiteAdminLogin({onBack,onSuccess}){const [u,setU]=useState('');const [p,setP]=useState('');const [err,setErr]=useState('');function submit(){if(u.trim().toLowerCase()==='websiteadmin'&&p==='KaShali@2026!')return onSuccess();setErr('Website administrator username or password is incorrect.')}return <div className="websiteAdminShell"><div className="websiteAdminLogin"><button className="backBtn" onClick={onBack}>← Back to website</button><img src="./school-logo.png" alt={SCHOOL_NAME}/><span className="eyebrow">WEBSITE ADMINISTRATION</span><h1>Website Control Panel</h1><p>Manage the public Ka-Shali website without entering the EduLink school-management system.</p><label>Username<input value={u} onChange={e=>setU(e.target.value)} autoComplete="username"/></label><label>Password<input type="password" value={p} onChange={e=>setP(e.target.value)} autoComplete="current-password"/></label><button className="primary full large" onClick={submit}>Sign in to Website Admin <ChevronRight size={17}/></button>{err&&<div className="error">{err}</div>}<small className="adminCredentialNote">Initial website administrator: <b>websiteadmin</b> / <b>KaShali@2026!</b>. Change the credentials before production use.</small></div></div>}\n\nfunction WebsiteAdmin({data,setData,onExit}){const site=data.website||WEBSITE_DEFAULTS;const [tab,setTab]=useState('dashboard');const [msg,setMsg]=useState('');const [form,setForm]=useState(()=>JSON.parse(JSON.stringify(site)));const update=(patch)=>setForm(x=>({...x,...patch}));function save(patch=form){setData(prev=>({...prev,website:{...prev.website,...patch}}));setMsg('Website changes saved successfully.');setTimeout(()=>setMsg(''),2500)}function reset(){if(confirm('Reset public website content to the V25 default content?')){setForm(JSON.parse(JSON.stringify(WEBSITE_DEFAULTS)));save(WEBSITE_DEFAULTS)}}function uploadImage(e,cb){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>cb(reader.result);reader.readAsDataURL(file);e.target.value=''}\n const nav=[['dashboard','Overview'],['home','Home & Hero'],['about','About School'],['courses','Courses'],['gallery','Gallery'],['contact','Contact'],['admissions','Admissions']];\n return <div className="websiteAdminShell"><aside className="websiteAdminSide"><div className="websiteAdminBrand"><img src="./school-logo.png" alt=""/><div><b>Website Admin</b><small>{SCHOOL_NAME}</small></div></div>{nav.map(([k,l])=><button key={k} className={tab===k?'active':''} onClick={()=>setTab(k)}>{l}</button>)}<div className="websiteAdminSideBottom"><button onClick={()=>window.open(location.href,'_blank')}>View public website</button><button onClick={onExit}>Sign out</button></div></aside><main className="websiteAdminMain"><header className="websiteAdminTop"><div><span className="eyebrow">PUBLIC WEBSITE MANAGEMENT</span><h1>{nav.find(n=>n[0]===tab)?.[1]||'Website Admin'}</h1></div><button className="outline" onClick={()=>save()}>Save all changes <Save size={16}/></button></header>{msg&&<div className="successBox">{msg}</div>}\n {tab==='dashboard'&&<WebsiteAdminOverview site={site setForm?form:site} setTab={setTab}/>}\n {tab==='home'&&<WebsiteHomeEditor form={form} update={update} uploadImage={uploadImage} save={save}/>}\n {tab==='about'&&<WebsiteAboutEditor form={form} update={update} save={save}/>}\n {tab==='courses'&&<WebsiteCoursesEditor form={form} setForm={setForm} save={save}/>}\n {tab==='gallery'&&<WebsiteGalleryEditor form={form} setForm={setForm} uploadImage={uploadImage} save={save}/>}\n {tab==='contact'&&<WebsiteContactEditor form={form} update={update} save={save}/>}\n {tab==='admissions'&&<WebsiteAdmissionsEditor form={form} update={update} save={save}/>}\n </main></div>}\nfunction WebsiteAdminOverview({site,setTab}){const cards=[['home','Home','Hero slides, welcome message and school highlights.'],['about','About School','School description, details and motto.'],['courses','Courses','Programme names, fees, descriptions and visibility.'],['gallery','Gallery','Public gallery photographs and captions.'],['contact','Contact','WhatsApp, email and school address.'],['admissions','Admissions','Public admissions message and call-to-action.']];return <div className="websiteAdminCards">{cards.map(([k,t,d])=><button key={k} onClick={()=>setTab(k)}><span>{t}</span><small>{d}</small><ChevronRight/></button>)}</div>}\nfunction WebsiteHomeEditor({form,update,uploadImage,save}){const slides=form.heroSlides||[];function changeSlide(i,patch){update({heroSlides:slides.map((x,n)=>n===i?{...x,...patch}:x)})}function add(){update({heroSlides:[...slides,{id:uid('H'),image:'./school-people.jpg',eyebrow:'KA-SHALI',title:'New school highlight',text:'Add a message for visitors.'}]})}function remove(i){if(slides.length<=1)return;update({heroSlides:slides.filter((_,n)=>n!==i)})}return <div className="websiteEditor"><Panel title="Home content"><label>Welcome heading<input value={form.welcomeTitle||''} onChange={e=>update({welcomeTitle:e.target.value})}/></label><label>Welcome text<textarea rows="4" value={form.welcomeText||''} onChange={e=>update({welcomeText:e.target.value})}/></label></Panel><Panel title="Hero slides"><div className="adminSlideList">{slides.map((s,i)=><div className="adminSlide" key={s.id||i}><div className="adminSlideImage"><img src={s.image} alt=""/></div><div className="adminSlideFields"><label>Eyebrow<input value={s.eyebrow||''} onChange={e=>changeSlide(i,{eyebrow:e.target.value})}/></label><label>Title<input value={s.title||''} onChange={e=>changeSlide(i,{title:e.target.value})}/></label><label>Message<textarea rows="3" value={s.text||''} onChange={e=>changeSlide(i,{text:e.target.value})}/></label><label>Image<input type="file" accept="image/*" onChange={e=>uploadImage(e,v=>changeSlide(i,{image:v}))}/></label><button className="small danger" onClick={()=>remove(i)}><Trash2 size={14}/> Remove slide</button></div></div>)}</div><button className="primary" onClick={add}><Plus size={16}/> Add hero slide</button><button className="outline" onClick={()=>save()}>Save Home changes <Save size={16}/></button></Panel></div>}\nfunction WebsiteAboutEditor({form,update,save}){return <div className="websiteEditor"><Panel title="About the school"><label>Page title<input value={form.aboutTitle||''} onChange={e=>update({aboutTitle:e.target.value})}/></label><label>Introduction<textarea rows="5" value={form.aboutText||''} onChange={e=>update({aboutText:e.target.value})}/></label><label>Full details<textarea rows="8" value={form.aboutDetails||''} onChange={e=>update({aboutDetails:e.target.value})}/></label><label>School motto<input value={form.motto||''} onChange={e=>update({motto:e.target.value})}/></label><button className="primary" onClick={()=>save()}><Save size={16}/> Save About changes</button></Panel></div>}\nfunction WebsiteCoursesEditor({form,setForm,save}){const list=form.courses||[];function change(i,patch){setForm(x=>({...x,courses:list.map((c,n)=>n===i?{...c,...patch}:c)}))}return <div className="websiteEditor"><Panel title="Public courses & programmes"><p className="muted">These are the programmes visitors see on the public Courses page. EduLink academic functions are not changed by this editor.</p><div className="adminCourseList">{list.map((c,i)=><div className="adminCourse" key={c.id||i}><label>Programme<input value={c.title||''} onChange={e=>change(i,{title:e.target.value})}/></label><label>Category<input value={c.category||''} onChange={e=>change(i,{category:e.target.value})}/></label><label>Description<textarea rows="3" value={c.description||''} onChange={e=>change(i,{description:e.target.value})}/></label><label>Fee<input type="number" value={c.fee??''} onChange={e=>change(i,{fee:e.target.value===''?null:Number(e.target.value)})}/></label><label className="checkLine"><input type="checkbox" checked={c.visible!==false} onChange={e=>change(i,{visible:e.target.checked})}/> Display publicly</label></div>)}</div><button className="primary" onClick={()=>save()}><Save size={16}/> Save Courses</button></Panel></div>}\nfunction WebsiteGalleryEditor({form,setForm,uploadImage,save}){const list=form.gallery||[];function change(i,patch){setForm(x=>({...x,gallery:list.map((g,n)=>n===i?{...g,...patch}:g)}))}function add(){setForm(x=>({...x,gallery:[...list,{id:uid('G'),image:'./school-people.jpg',title:'New school photo',text:'Add a caption for visitors.'}]}))}return <div className="websiteEditor"><Panel title="Public gallery"><div className="adminGalleryList">{list.map((g,i)=><div className="adminGalleryItem" key={g.id||i}><img src={g.image} alt=""/><label>Title<input value={g.title||''} onChange={e=>change(i,{title:e.target.value})}/></label><label>Caption<textarea rows="2" value={g.text||''} onChange={e=>change(i,{text:e.target.value})}/></label><label>Replace image<input type="file" accept="image/*" onChange={e=>uploadImage(e,v=>change(i,{image:v}))}/></label><button className="small danger" onClick={()=>setForm(x=>({...x,gallery:list.filter((_,n)=>n!==i)}))}><Trash2 size={14}/> Remove</button></div>)}</div><button className="primary" onClick={add}><Plus size={16}/> Add photo</button><button className="outline" onClick={()=>save()}><Save size={16}/> Save Gallery</button></Panel></div>}\nfunction WebsiteContactEditor({form,update,save}){return <div className="websiteEditor"><Panel title="Contact details"><label>School name<input value={form.siteName||''} onChange={e=>update({siteName:e.target.value})}/></label><label>Address<input value={form.address||''} onChange={e=>update({address:e.target.value})}/></label><label>WhatsApp / Call 1<input value={form.phone1||''} onChange={e=>update({phone1:e.target.value})}/></label><label>WhatsApp / Call 2<input value={form.phone2||''} onChange={e=>update({phone2:e.target.value})}/></label><label>Email<input type="email" value={form.email||''} onChange={e=>update({email:e.target.value})}/></label><button className="primary" onClick={()=>save()}><Save size={16}/> Save Contact details</button></Panel></div>}\nfunction WebsiteAdmissionsEditor({form,update,save}){return <div className="websiteEditor"><Panel title="Admissions content"><label>Heading<input value={form.admissionTitle||''} onChange={e=>update({admissionTitle:e.target.value})}/></label><label>Public message<textarea rows="5" value={form.admissionText||''} onChange={e=>update({admissionText:e.target.value})}/></label><button className="primary" onClick={()=>save()}><Save size={16}/> Save Admissions</button></Panel></div>}\n\n'''
